3	//! User-memory IPC message copies.
4	//!
5	//! Each `mini_send` / `mini_receive` / `mini_notify` handler accepts a
6	//! user-supplied VA in `frame.x[2]`. The kernel reads the outgoing
7	//! [`Message`] out of that buffer when the caller blocks, and writes the
8	//! incoming `Message` back to that buffer when the kernel resumes the
9	//! caller (the `MF_DELIVERMSG` flush).
10	//!
11	//! Slice 2.5's MMU is a single hand-rolled TTBR0 set up by
12	//! `arch::aarch64::userland_bootstrap`: one shared code page (now two —
13	//! one per stub) and per-task stack pages all under `USER_VA_TOP`. Because
14	//! the same TTBR0 is live across every EL0 task in this slice, reading
15	//! and writing user-mode VAs from EL1 just walks the active TTBR0; no
16	//! switch is needed.
17	//!
18	//! We do a coarse bounds check and let the hardware fault if a stub ever
19	//! passes a pointer into an unmapped page. Slice 2.5's stubs always pass
20	//! a stack-resident buffer, so this is unreachable in practice; phase 3's
21	//! VM server replaces this entire helper with a fault-recovering
22	//! `copy_from_user` once per-process page tables exist.
23	
24	use minixrs_kernel_shared::error::EFAULT;
25	use minixrs_kernel_shared::message::Message;
26	
27	/// One past the highest user VA reachable through TTBR0. Limine programs
28	/// `TCR_EL1.T0SZ = 16`, giving a 48-bit user VA space (`[0, 2^48)`); the
29	/// kernel's HHDM lives in the very high half via TTBR1 and is unreachable
30	/// from this range.
31	pub const USER_VA_TOP: u64 = 1 << 48;
32	
33	/// Bounds check for a user pointer of length `len` starting at `va`.
34	///
35	/// Rejects:
36	///   - NULL or sub-alignment-of-`Message` addresses (a NULL pointer or an
37	///     unaligned `read_volatile` is UB even before the access faults).
38	///   - Pointers whose range extends past `USER_VA_TOP`.
39	#[inline]
40	fn user_va_ok(va: u64, len: usize) -> bool {
41	    if va < core::mem::align_of::<Message>() as u64 {
42	        return false;
43	    }
44	    if !va.is_multiple_of(core::mem::align_of::<Message>() as u64) {
45	        return false;
46	    }
47	    match va.checked_add(len as u64) {
48	        Some(end) => end <= USER_VA_TOP,
49	        None => false,
50	    }
51	}
52	
53	/// Copy a [`Message`] out of user memory at `va`.
54	///
55	/// SAFETY: walks the currently-active TTBR0. We assume the same single-
56	/// threaded SVC/IRQ-masked invariant the rest of the IPC code relies on,
57	/// so no concurrent unmap can race the read. If `va` is in range but
58	/// unmapped, the EL1 access faults and we panic via the slice-2.4
59	/// `el0_sync_unexpected` path — acceptable until phase 3 adds a real
60	/// fault-recovering copy.
61	pub(crate) fn copy_msg_from_user(va: u64) -> Result<Message, i32> {
62	    if !user_va_ok(va, core::mem::size_of::<Message>()) {
63	        return Err(EFAULT);
64	    }
65	    // SAFETY: bounds-checked above; `Message` alignment confirmed; under
66	    // the single-threaded SVC invariant no concurrent writer exists.
67	    let m = unsafe { core::ptr::read_volatile(va as *const Message) };
68	    Ok(m)
69	}
70	
71	/// Write a [`Message`] into user memory at `va`.
72	///
73	/// See [`copy_msg_from_user`] for the SAFETY discussion.
74	pub(crate) fn copy_msg_to_user(va: u64, m: &Message) -> Result<(), i32> {
75	    if !user_va_ok(va, core::mem::size_of::<Message>()) {
76	        return Err(EFAULT);
77	    }
78	    // SAFETY: bounds-checked above; same single-threaded invariant.
79	    unsafe {
80	        core::ptr::write_volatile(va as *mut Message, *m);
81	    }
82	    Ok(())
83	}
84	
85	#[cfg(test)]
86	mod tests {
87	    use super::*;
88	
89	    #[test]
90	    fn user_va_ok_rejects_null() {
91	        assert!(!user_va_ok(0, core::mem::size_of::<Message>()));
92	    }
93	
94	    #[test]
95	    fn user_va_ok_rejects_unaligned() {
96	        assert!(!user_va_ok(0x10001, core::mem::size_of::<Message>()));
97	    }
98	
99	    #[test]
100	    fn user_va_ok_rejects_at_top() {
101	        assert!(!user_va_ok(USER_VA_TOP, core::mem::size_of::<Message>()));
102	    }
103	
104	    #[test]
105	    fn user_va_ok_rejects_overflow() {
106	        assert!(!user_va_ok(u64::MAX - 7, core::mem::size_of::<Message>()));
107	    }
108	
109	    #[test]
110	    fn user_va_ok_accepts_aligned_in_range() {
111	        // 8 MiB — where the slice's stub stacks live.
112	        assert!(user_va_ok(0x80_0000, core::mem::size_of::<Message>()));
113	    }
114	}
